// src/App.js
import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import Login from './components/Auth/Login';
import PrivateRoute from './components/Common/PrivateRoute';
import SelfDashboard from './components/Dashboard/SelfDashboard';
import HRDashboard from './components/Dashboard/HRDashboard';
import OthersDashboard from './components/Dashboard/OthersDashboard';
import './App.css';

function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="App">
          <Routes>
            {/* Public Route */}
            <Route path="/login" element={<Login />} />

            {/* Protected Routes */}
            <Route 
              path="/self-dashboard" 
              element={
                <PrivateRoute allowedRoles={['ROLE_SELF', 'ROLE_HR', 'ROLE_OTHERS']}>
                  <SelfDashboard />
                </PrivateRoute>
              } 
            />

            <Route 
              path="/hr-dashboard" 
              element={
                <PrivateRoute allowedRoles={['ROLE_HR']}>
                  <HRDashboard />
                </PrivateRoute>
              } 
            />

            <Route 
              path="/others-dashboard" 
              element={
                <PrivateRoute allowedRoles={['ROLE_OTHERS']}>
                  <OthersDashboard />
                </PrivateRoute>
              } 
            />

            {/* Default Route */}
            <Route path="/" element={<Navigate to="/login" replace />} />

            {/* 404 Route */}
            <Route path="*" element={<Navigate to="/login" replace />} />
          </Routes>
        </div>
      </Router>
    </AuthProvider>
  );
}

export default App;
